files.reports.py:
CACHE = {}
READS = []

def query(tenant_id, report_id):
    READS.append((tenant_id, report_id))
    return {"tenant_id": tenant_id, "report_id": report_id}

def get_report(tenant_id, report_id):
    if report_id not in CACHE:
        CACHE[report_id] = query(tenant_id, report_id)
    return dict(CACHE[report_id])

files.test_reports.py:
import unittest
import reports

class ReportTest(unittest.TestCase):
    def setUp(self):
        reports.CACHE.clear()
        reports.READS.clear()
    def test_repeat(self):
        reports.get_report("a", 1)
        reports.get_report("a", 1)
        self.assertEqual(len(reports.READS), 1)

if __name__ == "__main__":
    unittest.main()

